\begin{figure}[t]
\centering
\includegraphics[width=0.78\linewidth]{figures/fig4_federated.pdf}
\caption{Federated robustness across ten sites. \rev{Non-IID heterogeneity erodes
ECGFounder's lead while the hand-crafted representation retains 0.92 of its centralized
ARI.} \rev{The cohort of 2\,542 records partitioned across ten simulated sites over ten seeds, with
the site partition and the centroid initialisation redrawn at each seed. Error bars are 95\%
bootstrap intervals over the ten seeds, which under non-IID partitioning is the spread over
the site draws: [0.382, 0.796] for ECGFounder against [0.546, 0.631] for the hand-crafted
features.}}
\label{fig:fed}
\end{figure}
